      'in lockstep)', () {
    final a = pinnedRef(teammate, 'factory-teammate.yml');
    final b = pinnedRef(sm, 'factory-sm.yml');
    final c = pinnedRef(merge, 'factory-merge.yml');
    expect(
      a,
      b,
      reason:
