        yaml.contains(
          'SOURCE_GITHUB_TOKEN: \${{ secrets.SOURCE_GITHUB_TOKEN }}',
        ),
        isTrue,
        reason: '${entry.key}: SOURCE_GITHUB_TOKEN must be mapped explicitly',
      );
