import 'dart:io';
import 'package:test/test.dart';

void main() {
  // Live 2026-09-29: machine-sm.yml's workflow_dispatch input dryRun
  // defaults to TRUE — a flagless `gh workflow run machine-sm.yml` is a
  // dry no-op that only logs the plan, so the kicker's rescue tick saved
  // nothing (pr-1092). Pin the whole class: any dispatch site of
  // machine-sm.yml must state dryRun explicitly.
  final workflows = Directory('.github/workflows')
      .listSync()
      .whereType<File>()
      .where((f) => f.path.endsWith('.yml'));

  test('every machine-sm.yml dispatch passes an explicit -f dryRun= flag', () {
    final sites = <String>[];
    for (final f in workflows) {
      final lines = f.readAsLinesSync();
      for (var i = 0; i < lines.length; i++) {
        final line = lines[i];
        if (!line.contains('gh workflow run machine-sm.yml')) continue;
        sites.add('${f.path}:${i + 1}');
        expect(
          RegExp(r'-f\s+dryRun=(true|false)\b').hasMatch(line),
          isTrue,
          reason:
              '${f.path}:${i + 1} dispatches machine-sm.yml without an '
              'explicit `-f dryRun=` — the input defaults to true and the '
              'tick becomes a dry no-op (live: pr-1092)',
        );
      }
    }
    expect(sites, contains('.github/workflows/sm-kicker.yml'),
        reason: 'the kicker rescue dispatch must stay under guard');
  });
}
